    text: a.innerText.trim(),
    href: a.href
  })).filter(a => a.text.length > 2 && a.text.length < 30);

  return {
    title: document.title,
    recentArticles: articles.slice(0, 8),
    navItems: navItems.slice(0, 20)
  };
});
